def bit_dishes(str_dishes):
	dishes = [0] * 32
	(a, e, i, o, u) = (1, 1 << 1, 1 << 2, 1 << 3, 1 << 4)
	for str_dish in str_dishes:
		dish = 0
		for c in str_dish:
			if c == 'a':
				dish |= a
			elif c == 'e':
				dish |= e
			elif c == 'i':
				dish |= i
			elif c == 'o':
				dish |= o
			elif c == 'u':
				dish |= u
			if dish == 31:
				break
		dishes[dish] += 1
	return dishes

def count_good(dishes):
	res = 0
	for i in range(1, 32):
		for j in range(i + 1, 32):
			if i | j == 31:
				res += dishes[i] * dishes[j]
	res += dishes[31] * (dishes[31] - 1) // 2
	return res
trials = int(input())
for _ in range(trials):
	n = int(input())
	dishes = [''] * n
	for i in range(n):
		dishes[i] = input()
	dishes = bit_dishes(dishes)
	print(count_good(dishes))
